import { useState } from "react";
import type { ReactNode } from "react";
import { Modal, Pressable, StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface DrawerProps {
  trigger?: ReactNode;
  title: string;
  description?: string;
  children: ReactNode;
  side?: "left" | "right" | "top" | "bottom";
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Extend the inner, named parts of the drawer: overlay, panel, header, title, description or body. The React Native counterpart of `classNames`. */
  styles?: {
    overlay?: StyleProp<ViewStyle>;
    panel?: StyleProp<ViewStyle>;
    title?: StyleProp<TextStyle>;
    description?: StyleProp<TextStyle>;
    body?: StyleProp<ViewStyle>;
  };
}

/** A panel that slides in from an edge of the screen. */
export function Drawer({ trigger, title, description, children, side = "right", open, defaultOpen = false, onOpenChange, styles: parts }: DrawerProps) {
  const tokens = useTokens();
  const [internal, setInternal] = useState(defaultOpen);
  const visible = open ?? internal;
  const horizontal = side === "left" || side === "right";

  function change(next: boolean) {
    if (open === undefined) setInternal(next);
    onOpenChange?.(next);
  }

  const align = { left: { alignItems: "flex-start" }, right: { alignItems: "flex-end" }, top: { justifyContent: "flex-start" }, bottom: { justifyContent: "flex-end" } }[side] as ViewStyle;

  return (
    <>
      {trigger ? (
        <Pressable accessibilityRole="button" onPress={() => change(true)} style={{ alignSelf: "flex-start" }}>
          {trigger}
        </Pressable>
      ) : null}
      <Modal transparent animationType="fade" visible={visible} onRequestClose={() => change(false)} statusBarTranslucent>
        <Pressable accessibilityLabel="Close drawer" onPress={() => change(false)} style={[local.overlay, align, parts?.overlay]}>
          <Pressable
            accessibilityViewIsModal
            onPress={() => undefined}
            style={[
              local.panel,
              horizontal ? { width: "85%", maxWidth: 380, height: "100%" } : { width: "100%", maxHeight: "70%" },
              { borderColor: tokens.border, backgroundColor: tokens.surface },
              parts?.panel,
            ]}
          >
            <View style={local.header}>
              <View style={{ flex: 1, gap: 4 }}>
                <Text accessibilityRole="header" style={[{ color: tokens.foreground, fontSize: metrics.text.lg, fontWeight: "500" }, parts?.title]}>{title}</Text>
                {description ? <Text style={[{ color: tokens.textSecondary, fontSize: metrics.text.sm }, parts?.description]}>{description}</Text> : null}
              </View>
              <Pressable accessibilityRole="button" accessibilityLabel="Close" hitSlop={8} onPress={() => change(false)}>
                <Text style={{ color: tokens.textMuted, fontSize: 20, lineHeight: 22 }}>×</Text>
              </Pressable>
            </View>
            <View style={[local.body, parts?.body]}>{children}</View>
          </Pressable>
        </Pressable>
      </Modal>
    </>
  );
}

const local = StyleSheet.create({
  overlay: { flex: 1, backgroundColor: "rgba(10, 10, 10, 0.4)" },
  panel: { borderWidth: 1, padding: metrics.space[5], gap: metrics.space[4] },
  header: { flexDirection: "row", alignItems: "flex-start", gap: metrics.space[3] },
  body: { gap: metrics.space[3] },
});

export default Drawer;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
